<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_admin();require __DIR__.'/_layout.php';
$projects=db()->query('SELECT id,title,category,status,featured,sort_order FROM projects ORDER BY sort_order,id DESC')->fetchAll();
admin_header('Manage projects');?><div class="toolbar"><p>Update project content, links, statuses, and screenshots.</p><a class="btn btn-primary" href="<?= e(url('admin/edit-project.php')) ?>">+ Add project</a></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Project</th><th>Category</th><th>Status</th><th>Featured</th><th>Actions</th></tr></thead><tbody><?php foreach($projects as $p): ?><tr><td><strong><?= e($p['title']) ?></strong></td><td><?= e($p['category']) ?></td><td><?= e(project_status($p['status'])) ?></td><td><?= $p['featured'] ? 'Yes' : 'No' ?></td><td class="actions"><a href="<?= e(url('admin/edit-project.php?id='.$p['id'])) ?>">Edit</a><form method="post" action="<?= e(url('admin/delete-project.php')) ?>" onsubmit="return confirm('Delete this project permanently?')"><input type="hidden" name="csrf" value="<?= e(token()) ?>"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php admin_footer(); ?>
